#' Chi-Square Post-Tests
#'
#' 
#' @param data .
#' @param rows .
#' @param cols .
#' @param counts .
#' @param adjustment .
#' @param alpha .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$overall} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cells} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pairs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overall$asDF}
#'
#' \code{as.data.frame(results$overall)}
#'
#' @export
pychisqposttest <- function(
    data,
    rows = NULL,
    cols = NULL,
    counts = NULL,
    adjustment = "bonferroni",
    alpha = 0.05,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pychisqposttest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rows)) rows <- jmvcore::resolveQuo(jmvcore::enquo(rows))
    if ( ! missing(cols)) cols <- jmvcore::resolveQuo(jmvcore::enquo(cols))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rows), rows, NULL),
            `if`( ! missing(cols), cols, NULL),
            `if`( ! missing(counts), counts, NULL))

    for (v in rows) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in cols) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pychisqposttestOptions$new(
        rows = rows,
        cols = cols,
        counts = counts,
        adjustment = adjustment,
        alpha = alpha,
        showConsole = showConsole)

    analysis <- pychisqposttestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

